#!/bin/bash
# Generated by scripts/export-killercoda.ts. Passes (exit 0) when the named checks of lab-m11-shelf-worker pass.
# Environment overrides, for local tests: SHELF_BIN, KUBECONFIG, SHELF_MARKER_DIR, SHELF_COURSE_DIR, SHELF_LABS_DIR.
LAB=lab-m11-shelf-worker
CHECKS="reindex-indexed reindex-ttl reindex-succeeded reindex-completed-indexes"
MARK="${SHELF_MARKER_DIR:-/tmp}"
SHELF="${SHELF_BIN:-/usr/local/bin/shelf}"
[ -f "$MARK/shelf-failed" ] && { echo "Setup failed: $(cat "$MARK/shelf-failed"). See /tmp/shelf-setup.log." >&2; exit 1; }
[ -f "$MARK/shelf-ready" ] || { echo "Setup is not finished. Wait for RESULT: ready in the first terminal, then click Check again." >&2; exit 1; }
export KUBECONFIG="${KUBECONFIG:-/root/.kube/config}"
cd "${SHELF_COURSE_DIR:-/root/course}" || { echo "The course folder is missing." >&2; exit 1; }
kubectl --context kind-reconcile --request-timeout=10s get nodes >/dev/null 2>&1 || { echo "The cluster is not reachable. Create it first (shelf up), and wait for the node to be Ready." >&2; exit 1; }
# Only this step's checks run, and each wait is capped at 30 s: the lab's own checks.yaml is replaced in a temporary copy of the labs folder.
LABS="${SHELF_LABS_DIR:-${SHELF_COURSE_DIR:-/root/course}/labs}"
T=$(mktemp -d) || { echo "Cannot make a temporary folder." >&2; exit 1; }
trap '[ -n "$T" ] && rm -rf "$T"' EXIT
for e in "$LABS"/*; do n=${e##*/}; [ "$n" = "$LAB" ] || ln -s "$e" "$T/$n"; done
cp -R "$LABS/$LAB" "$T/$LAB"
cat > "$T/$LAB/checks.yaml" <<'KILLERCODA_CHECKS'
apiVersion: labs.reconcile.example/v1
kind: LabChecks
lab: lab-m11-shelf-worker
checks:
  - id: reindex-indexed
    describe: The reindex Job is Indexed, with 4 completions and 2 at a time
    kubectl:
      - get
      - job
      - shelf-reindex
      - -n
      - shelf
      - -o
      - jsonpath={.spec.completionMode}/{.spec.completions}/{.spec.parallelism}
    expect:
      equals: Indexed/4/2
    hint: "Add `completionMode: Indexed`, `completions: 4` and `parallelism: 2` under the Job's `spec`. `completions` must equal `SHELF_WORKER_SHARDS`, or some rows are never rebuilt. A Job's Pod template can't have `restartPolicy: Always`: use `Never`, then apply the file."
  - id: reindex-ttl
    describe: The reindex Job has a time to live after it finishes
    kubectl:
      - get
      - job
      - shelf-reindex
      - -n
      - shelf
      - -o
      - jsonpath={.spec.ttlSecondsAfterFinished}
    expect:
      matches: ^[1-9][0-9]{2,}$
    hint: "Add `ttlSecondsAfterFinished: 3600` under the Job's `spec`. Use at least 100 seconds, so that the Job is still there when you run the checks."
  - id: reindex-succeeded
    describe: All 4 indexes of the reindex Job have succeeded
    kubectl:
      - get
      - job
      - shelf-reindex
      - -n
      - shelf
      - -o
      - jsonpath={.status.succeeded}
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          equals: "4"
    hint: "Wait for the Pods: `kubectl get pods --namespace shelf --selector job-name=shelf-reindex`. If a Pod shows `Error`, read its log. A Job applied before the api was ready fails on its first attempts: delete it with `kubectl delete job shelf-reindex --namespace shelf` and apply it again."
  - id: reindex-completed-indexes
    describe: Every index from 0 to 3 is in status.completedIndexes
    kubectl:
      - get
      - job
      - shelf-reindex
      - -n
      - shelf
      - -o
      - jsonpath={.status.completedIndexes}
    expect:
      equals: 0-3
    hint: "`completedIndexes` lists the indexes that succeeded once. It reads `0-3` when each of the four Pods has finished."
KILLERCODA_CHECKS
out=$(SHELF_LABS_DIR="$T" timeout 60 "$SHELF" verify "$LAB" 2>&1); rc=$?
if [ "$rc" -eq 124 ]; then echo "The checks took too long. Wait a few seconds and click Check again." >&2; exit 1; fi
if [ "$rc" -ge 2 ]; then echo "$out" >&2; exit 1; fi
bad=0
for id in $CHECKS; do
  printf '%s\n' "$out" | grep -Eq "^(PASS|SKIP) $id " && continue
  bad=1; printf '%s\n' "$out" | grep -E -A2 "^FAIL $id "
done
[ "$bad" -eq 0 ] || echo "If you just applied a change, it may still be rolling out: wait a few seconds and click Check again." >&2
exit "$bad"
